function vparse(s){var m=/^(\d+)\.(\d+)(?:\.(\d+))?$/.exec(String(s||"").trim());return m?[+m[1],+m[2],+(m[3]||0)]:null}
function vcmp(a,b){var x=vparse(a),y=vparse(b),i;if(!x||!y)return 0;for(i=0;i<3;i++)if(x[i]!==y[i])return x[i]<y[i]?-1:1;return 0}
