function addrBase(o){var m=/Entrega:\s*(.+?)(?:\s·\s*WhatsApp|\n|$)/.exec(o.obs||"");if(m&&m[1].trim())return m[1].trim();var c=cuOf(o);return c&&c.a?String(c.a).trim():""}
